import { useState } from "react";
import { Routes, Route } from "react-router-dom";
import Template from "./template/Template";
import ProductDetail from "./products/detail/ProductDetail";
import Landing from "./landing/Landing";
import ProductList from "./products/ProductList";

function App() {
  // 1. Quản lý State tập trung tại đây để làm cầu nối giữa Header và ProductList
  const [currentCategory, setCurrentCategory] = useState("");
  const [currentBrand, setCurrentBrand] = useState("");

  return (
    // Sử dụng component Template bao bọc toàn bộ hệ thống (Header nằm sẵn bên trong Template này)
    <Template setCategory={setCurrentCategory} setBrand={setCurrentBrand}>
      <Routes>
        {/* Trang chủ: Render ProductList và truyền State kèm hàm thay đổi State xuống */}
        <Route 
          path="/" 
          element={
            <ProductList 
              category={currentCategory} 
              setCategory={setCurrentCategory}
              brand={currentBrand}
              setBrand={setCurrentBrand}
            />
          } 
        />
        
        {/* Giữ lại đường dẫn cũ phòng trường hợp bạn bấm trên thanh điều hướng */}
        <Route 
          path="/products" 
          element={
            <ProductList 
              category={currentCategory} 
              setCategory={setCurrentCategory}
              brand={currentBrand}
              setBrand={setCurrentBrand}
            />
          } 
        />

        {/* Trang chi tiết sản phẩm: Đổi thành :id để khớp với cấu trúc dữ liệu số */}
        <Route path="/products/:id" element={<ProductDetail />} />
        
        {/* Trang Landing cũ của bạn */}
        <Route path="/landing" element={<Landing />} />
        
        {/* Trang Giới thiệu */}
        <Route
          path="/about"
          element={
            <div className="container mt-5 text-center">
              <h2>Trang About đang được xây dựng...</h2>
            </div>
          }
        />
        
        {/* Bắt lỗi trang 404 nếu gõ sai link */}
        <Route
          path="*"
          element={
            <div className="container mt-5 text-center">
              <h1 className="text-danger">404 - Không tìm thấy trang</h1>
              <p>Vui lòng quay lại trang chủ.</p>
            </div>
          }
        />
      </Routes>
    </Template>
  );
}

export default App;
